class FakeGoDaddyClient:
    """In-memory stand-in for tests and practice mode."""

    def __init__(self, available: dict[str, float] | None = None, env: str = "ote", owned: set[str] | None = None,
                 app_domain: str = ""):
        self.env = env
        self.app_domain = app_domain  # same write guard as the real client
        self.available = dict(available or {})  # domain -> price in USD
        self.owned: set[str] = set(owned or ())
        self.zones: dict[str, list[DnsRecord]] = {}
        self.calls: list[tuple] = []
        self.fail_next: dict[str, int] = {}  # method name -> number of upcoming calls that raise
        self.expires: dict[str, datetime] = {}  # domain -> registration end (default: a year from now)

    def _maybe_fail(self, method: str) -> None:
        if self.fail_next.get(method, 0) > 0:
            self.fail_next[method] -= 1
            raise RuntimeError(f"fake {method} failure")

    def check_availability(self, domain: str) -> dict:
        self.calls.append(("check_availability", domain))
        if domain in self.available and domain not in self.owned:
            return {"domain": domain, "available": True, "price_usd": self.available[domain]}
        return {"domain": domain, "available": False}

    def is_owned(self, domain: str) -> bool:
        self.calls.append(("is_owned", domain))
        return domain in self.owned

    def get_records(self, domain: str) -> list[DnsRecord]:
        self.calls.append(("get_records", domain))
        self._maybe_fail("get_records")
        return [dict(r) for r in self.zones.get(domain, [])]

    def set_records(self, domain: str, rtype: str, name: str, records: list[DnsRecord]) -> None:
        assert_zone_write(self.app_domain, domain, rtype, name)
        self.calls.append(("set_records", domain, rtype, name))
        self._maybe_fail("set_records")
        keep = [r for r in self.zones.get(domain, []) if not (r["type"] == rtype and r["name"] == name)]
        self.zones[domain] = keep + [{**dict(r), "type": rtype, "name": name} for r in records]

    def delete_records(self, domain: str, rtype: str, name: str) -> None:
        assert_zone_write(self.app_domain, domain, rtype, name)
        self.calls.append(("delete_records", domain, rtype, name))
        self.zones[domain] = [r for r in self.zones.get(domain, []) if not (r["type"] == rtype and r["name"] == name)]

    def purchase_domain(self, domain: str, price_usd: float) -> dict:
        self.calls.append(("purchase_domain", domain, price_usd))
        self.owned.add(domain)
        return {"domain": domain, "price_usd": price_usd, "order_id": f"fake-{len(self.owned)}"}

    def domain_expires(self, domain: str) -> datetime | None:
        if domain not in self.owned:
            return None
"""Public DNS lookups (dnspython) for launch checks."""

from typing import Protocol

import dns.exception
import dns.resolver


class DnsResolver(Protocol):
    def resolve(self, name: str, rtype: str) -> list[str]: ...


class RealDnsResolver:
    def __init__(self, nameservers: list[str] | None = None, timeout: float = 5.0):
        self._r = dns.resolver.Resolver()
        if nameservers:
            self._r.nameservers = nameservers
        self._r.lifetime = timeout

    def resolve(self, name: str, rtype: str) -> list[str]:
        try:
            answer = self._r.resolve(name, rtype)
        except (dns.resolver.NXDOMAIN, dns.resolver.NoAnswer, dns.exception.Timeout):
            return []
        return [r.to_text() for r in answer]


class FakeDnsResolver:
    def __init__(self, records: dict[tuple[str, str], list[str]] | None = None):
        self.records = dict(records or {})

    def set(self, name: str, rtype: str, values: list[str]) -> None:
        self.records[(name.lower().rstrip("."), rtype.upper())] = values

    def resolve(self, name: str, rtype: str) -> list[str]:
        return list(self.records.get((name.lower().rstrip("."), rtype.upper()), []))


def record_text(rec: dict) -> str:
    """GoDaddy record dict -> the text a DNS lookup would return."""
    if rec["type"] == "MX":
        return f"{rec.get('priority', 10)} {rec['data']}."
    if rec["type"] == "TXT":
        return f'"{rec["data"]}"'
    if rec["type"] in ("CNAME", "NS"):
        return rec["data"].rstrip(".") + "."
    return rec["data"]


class ZoneBackedResolver:
    """Fake *authoritative* DNS that answers from a FakeGoDaddyClient's zones,
    so practice-mode launches can be 'proven' end to end. `hide` lets tests and
    the demo fault simulate a record that hasn't spread yet / went missing."""

    def __init__(self, godaddy):
        self.godaddy = godaddy
        self.hide: set[tuple[str, str]] = set()

    def resolve(self, name: str, rtype: str) -> list[str]:
        fqdn, rtype = name.lower().rstrip("."), rtype.upper()
        if (fqdn, rtype) in self.hide:
            return []
        for zone, records in self.godaddy.zones.items():
            if fqdn == zone:
                label = "@"
            elif fqdn.endswith("." + zone):
                label = fqdn[: -len(zone) - 1]
            else:
                continue
            return [record_text(r) for r in records if r["type"] == rtype and r["name"] == label]
        return []


class AuthoritativeResolver:
    """Asks the zone's OWN nameservers (found from its NS records), not a cache, and remembers which
    server answered (`last_server`), so a check can say exactly where its answer came from."""

    def __init__(self, timeout: float = 5.0, finder=None, query=None):
        self.timeout = timeout
        self._finder = finder or RealDnsResolver(timeout=timeout)  # only to FIND the nameservers
        self._query = query or self._udp
        self.last_server = ""

    def _udp(self, name: str, rtype: str, ip: str) -> list[str]:
        import dns.message
        import dns.query
        import dns.rdatatype

        resp = dns.query.udp(dns.message.make_query(name, rtype), ip, timeout=self.timeout)
        want = dns.rdatatype.from_text(rtype)
        return [r.to_text() for rrset in resp.answer if rrset.rdtype == want for r in rrset]

    def nameservers(self, name: str) -> tuple[str, list[str]]:
        labels = name.lower().rstrip(".").split(".")
        for i in range(len(labels) - 1):
            zone = ".".join(labels[i:])
            ns = self._finder.resolve(zone, "NS")
            if ns:
                return zone, sorted(n.rstrip(".") for n in ns)
        return "", []

    def resolve(self, name: str, rtype: str) -> list[str]:
        _zone, ns = self.nameservers(name)
        for host in ns:
            for ip in self._finder.resolve(host, "A"):
                try:
                    answer = self._query(name, rtype, ip)
                except Exception:  # try the next nameserver
                    continue
                self.last_server = f"{host} ({ip})"
                return answer
        self.last_server = ""
        return []

